sp_widget.client_script:
api.controller = function($window, $timeout) {

    var c = this;

    /* =====================================================
       SIDEBAR
       ===================================================== */

    c.sidebarOpen = false;

    c.toggleSidebar = function() {
        c.sidebarOpen = !c.sidebarOpen;
    };

    c.closeSidebar = function() {
        c.sidebarOpen = false;
    };


    /* =====================================================
       NAVIGATION
       ===================================================== */

    c.navigate = function(pageId) {

        if (!pageId) {
            return;
        }

        var studentId = '';

        if (
            c.data &&
            c.data.student &&
            c.data.student.id
        ) {
            studentId = c.data.student.id;
        }

        if (!studentId) {
            studentId = 'STU_TEST_001';
        }

        var url =
            '?id=' +
            encodeURIComponent(pageId) +
            '&student=' +
            encodeURIComponent(studentId);

        c.closeSidebar();

        $window.location.href = url;
    };


    /* =====================================================
       TRAINER CREATED ASSIGNMENTS
       ===================================================== */

    c.assessmentDetailsOpen = false;

    c.selectedAssessment = null;


    c.openAssessments = function() {

        if (
            !c.data ||
            !c.data.assessments ||
            !c.data.assessments.length
        ) {

            c.assessmentDetailsOpen = false;
            c.selectedAssessment = null;

            return;
        }

        c.selectedAssessment =
            c.data.assessments[0];

        c.assessmentDetailsOpen = true;

        $timeout(function() {

            var details =
                document.querySelector(
                    '.c360-assessment-details'
                );

            if (details) {

                details.scrollIntoView({
                    behavior: 'smooth',
                    block: 'nearest'
                });
            }

        }, 80);
    };


    c.toggleAssessmentDetails = function() {

        if (
            !c.data ||
            !c.data.assessments ||
            !c.data.assessments.length
        ) {

            c.assessmentDetailsOpen = false;
            c.selectedAssessment = null;

            return;
        }

        c.assessmentDetailsOpen =
            !c.assessmentDetailsOpen;

        if (
            c.assessmentDetailsOpen &&
            !c.selectedAssessment
        ) {

            c.selectedAssessment =
                c.data.assessments[0];
        }

        if (c.assessmentDetailsOpen) {

            $timeout(function() {

                var details =
                    document.querySelector(
                        '.c360-assessment-details'
                    );

                if (details) {

                    details.scrollIntoView({
                        behavior: 'smooth',
                        block: 'nearest'
                    });
                }

            }, 80);
        }
    };


    c.openAssessment = function(assessment) {

        if (!assessment) {
            return;
        }

        c.selectedAssessment =
            assessment;

        c.assessmentDetailsOpen =
            true;

        $timeout(function() {

            var details =
                document.querySelector(
                    '.c360-assessment-details'
                );

            if (details) {

                details.scrollIntoView({
                    behavior: 'smooth',
                    block: 'nearest'
                });
            }

        }, 80);
    };


    c.closeAssessment = function() {

        c.selectedAssessment = null;

        c.assessmentDetailsOpen = false;
    };


    /* =====================================================
       TRAINER MODAL
       ===================================================== */

    c.selectedTrainer = null;

    c.selectedFeedback = null;


    c.openTrainer = function(trainer) {

        c.selectedTrainer = trainer;

        c.selectedFeedback = null;

        try {

            document.body.style.overflow =
                'hidden';

        } catch (e) {}
    };


    c.closeTrainer = function() {

        c.selectedTrainer = null;

        c.selectedFeedback = null;

        try {

            document.body.style.overflow =
                '';

        } catch (e) {}
    };


    /* =====================================================
       FEEDBACK MODAL
       ===================================================== */

    c.openFeedback = function(feedback) {

        c.selectedFeedback =
            feedback;
    };


    c.closeFeedback = function() {

        c.selectedFeedback =
            null;
    };


    /* =====================================================
       ESCAPE KEY
       ===================================================== */

    c.onKeyDown = function(event) {

        if (
            event &&
            event.keyCode === 27
        ) {

            if (c.selectedFeedback) {

                c.closeFeedback();

                return;
            }

            if (c.selectedTrainer) {

                c.closeTrainer();

                return;
            }

            if (c.assessmentDetailsOpen) {

                c.closeAssessment();

                return;
            }

            if (c.sidebarOpen) {

                c.closeSidebar();
            }
        }
    };


    /* =====================================================
       CLEANUP
       ===================================================== */

    c.$onDestroy = function() {

        try {

            document.body.style.overflow =
                '';

        } catch (e) {}
    };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 STUDENT TRAINING
   FINAL FULL-VIEW / FULL SCREEN VERSION
   ========================================================= */


/* =========================================================
   GLOBAL RESET
   ========================================================= */

html,
body {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    max-width: none !important;
}


/* =========================================================
   HIDE SERVICENOW GLOBAL NAVBAR
   ========================================================= */

body:has(.campus360-training) #sp-nav,
body:has(.campus360-training) .sp-navbar,
body:has(.campus360-training) .sp-header,
body:has(.campus360-training) .sp-header-bar,
body:has(.campus360-training) .portal-header,
body:has(.campus360-training) .navbar,
body:has(.campus360-training) .navbar-default,
body:has(.campus360-training) header.navbar {
    display: none !important;
}


/* =========================================================
   SERVICENOW OUTER WRAPPER RESET
   ========================================================= */

body:has(.campus360-training) .container,
body:has(.campus360-training) .container-fluid,
body:has(.campus360-training) .row,
body:has(.campus360-training) [class*="col-"],
body:has(.campus360-training) .well,
body:has(.campus360-training) .panel {
    width: 100% !important;
    max-width: none !important;
    margin: 0 !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
}

body:has(.campus360-training) .panel-body {
    width: 100% !important;
    max-width: none !important;
    margin: 0 !important;
    padding: 0 !important;
}


/* =========================================================
   ROOT
   ========================================================= */

.campus360-training {
    position: fixed !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    min-width: 100vw !important;
    min-height: 100vh !important;
    max-width: 100vw !important;
    max-height: 100vh !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;

    background:
        linear-gradient(
            135deg,
            #f1f6fc 0%,
            #f7f4ff 50%,
            #f0f8f6 100%
        );

    color: #172033;

    font-family:
        Inter,
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Arial,
        sans-serif;

    z-index: 999999 !important;
}

.campus360-training *,
.campus360-training *::before,
.campus360-training *::after {
    box-sizing: border-box;
}


/* =========================================================
   STUDENT SIDEBAR - DARK PURPLE
   ========================================================= */

.c360-student-sidebar {
    position: absolute !important;
    left: 0;
    top: 0;
    bottom: 0;

    width: 285px !important;
    min-width: 285px !important;
    max-width: 285px !important;

    height: 100vh !important;
    min-height: 100vh !important;

    display: flex;
    flex-direction: column;

    background:
        linear-gradient(
            180deg,
            #130d2f 0%,
            #160d38 48%,
            #100a29 100%
        ) !important;

    border-right: 1px solid #2d2157 !important;

    box-shadow:
        4px 0 18px
        rgba(25, 10, 60, .20);

    overflow: hidden;

    z-index: 100;

    transform: translateX(0);
    transition: transform .25s ease;
}


/* CLOSED DESKTOP */

.campus360-training.sidebar-closed
.c360-student-sidebar {
    transform: translateX(-105%);
}


/* =========================================================
   BRAND
   ========================================================= */

.c360-sidebar-brand {
    height: 88px;
    min-height: 88px;
    flex: 0 0 88px;

    padding: 0 20px;

    display: flex;
    align-items: center;
    gap: 12px;

    border-bottom: 1px solid #2d2157;
}

.c360-brand-mark {
    width: 48px;
    height: 48px;
    min-width: 48px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 14px;

    background:
        linear-gradient(
            135deg,
            #7c3aed,
            #9333ea
        );

    color: #ffffff;

    font-size: 23px;
    font-weight: 900;

    box-shadow:
        0 7px 18px
        rgba(124, 58, 237, .34);
}

.c360-brand-text {
    min-width: 0;
}

.c360-brand-text strong {
    display: block;

    color: #ffffff;

    font-size: 20px;
    line-height: 1;
    font-weight: 900;
}

.c360-brand-text span {
    display: block;

    margin-top: 5px;

    color: #c4b5fd;

    font-size: 11px;
    font-weight: 800;
}


/* =========================================================
   STUDENT CARD
   ========================================================= */

.c360-sidebar-student {
    margin:
        18px
        13px
        10px;

    min-height: 67px;

    padding: 12px;

    display: flex;
    align-items: center;
    gap: 10px;

    border: 1px solid #3a2d68;
    border-radius: 14px;

    background: #1d1440;

    color: inherit !important;
    text-decoration: none !important;

    transition:
        border-color .18s ease,
        box-shadow .18s ease,
        background .18s ease;
}

.c360-sidebar-student:hover {
    border-color: #6246a8;

    background: #24174d;

    box-shadow:
        0 6px 16px
        rgba(124, 58, 237, .14);
}

.c360-sidebar-avatar {
    width: 43px;
    height: 43px;
    min-width: 43px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background:
        linear-gradient(
            135deg,
            #7c5ce8,
            #6d4fe1
        );

    color: #ffffff;

    font-size: 11px;
    font-weight: 900;
}

.c360-sidebar-student-info {
    min-width: 0;
    flex: 1;
}

.c360-sidebar-student-info strong {
    display: block;

    max-width: 185px;

    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;

    color: #ffffff;

    font-size: 13px;
    font-weight: 900;
}

.c360-sidebar-student-info span {
    display: block;

    margin-top: 3px;

    color: #aaa0c7;

    font-size: 10px;
    font-weight: 600;
}

.c360-student-arrow {
    color: #a99fc7;
    font-size: 21px;
}


/* =========================================================
   SIDEBAR NAV
   ========================================================= */

.c360-sidebar-nav {
    flex: 1 1 auto;
    min-height: 0;

    padding:
        2px
        8px
        12px;

    overflow-y: auto;
    overflow-x: hidden;
}

.c360-sidebar-nav::-webkit-scrollbar {
    width: 5px;
}

.c360-sidebar-nav::-webkit-scrollbar-track {
    background: transparent;
}

.c360-sidebar-nav::-webkit-scrollbar-thumb {
    background: #40326e;
    border-radius: 10px;
}

.c360-nav-group {
    margin-bottom: 4px;
}

.c360-nav-label {
    padding:
        17px
        9px
        8px;

    color: #8f84ae;

    font-size: 10px;
    font-weight: 900;
    letter-spacing: .11em;
}

.c360-nav-item {
    position: relative;

    width: 100%;
    min-height: 46px;

    margin:
        3px
        0;

    padding:
        9px
        12px;

    display: flex;
    align-items: center;
    gap: 12px;

    border: 0;
    border-radius: 11px;

    background: transparent;

    color: #d8d0eb !important;

    font-family: inherit;
    font-size: 14px;
    font-weight: 750;

    text-decoration: none !important;

    cursor: pointer;

    transition:
        background .18s ease,
        color .18s ease,
        transform .18s ease;
}

.c360-nav-item:hover {
    color: #ffffff !important;

    background:
        rgba(124, 58, 237, .18);

    transform:
        translateX(2px);
}

.c360-nav-item.active {
    color: #ffffff !important;

    background:
        linear-gradient(
            90deg,
            #7c3aed 0%,
            #8b3ff2 100%
        );

    font-weight: 900;

    box-shadow:
        0 6px 16px
        rgba(124, 58, 237, .24);
}

.c360-nav-item.active::before {
    content: "";

    position: absolute;

    left: 0;
    top: 8px;
    bottom: 8px;

    width: 4px;

    border-radius:
        0
        4px
        4px
        0;

    background: #ffffff;
}

.c360-nav-icon {
    width: 24px;
    height: 24px;
    min-width: 24px;

    display: flex;
    align-items: center;
    justify-content: center;

    color: #a99fc7;
}

.c360-nav-icon svg {
    width: 21px;
    height: 21px;

    fill: none;
    stroke: currentColor;

    stroke-width: 1.8;

    stroke-linecap: round;
    stroke-linejoin: round;
}

.c360-nav-item.active
.c360-nav-icon {
    color: #ffffff;
}

.c360-nav-item > span:last-child {
    min-width: 0;
    flex: 1;

    white-space: nowrap;
}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.c360-sidebar-footer {
    flex: 0 0 auto;

    padding:
        10px
        12px
        13px;

    border-top: 1px solid #2d2157;
}

.c360-journey-mini {
    padding: 12px;

    border:
        1px solid #3a2d68;

    border-radius: 12px;

    background: #1a1138;
}

.c360-journey-label {
    color: #9d91b8;

    font-size: 9px;
    font-weight: 900;
    letter-spacing: .08em;
}

.c360-journey-progress {
    height: 7px;

    margin-top: 9px;

    overflow: hidden;

    border-radius: 8px;

    background: #302454;
}

.c360-journey-fill {
    height: 100%;

    border-radius: 8px;

    background:
        linear-gradient(
            90deg,
            #7c3aed,
            #a855f7
        );
}

.c360-journey-score {
    margin-top: 6px;

    color: #9d91b8;

    font-size: 10px;
    font-weight: 700;
}


/* =========================================================
   RIGHT MAIN PAGE
   ========================================================= */

.c360-training-main {
    position: absolute !important;

    top: 0;
    right: 0;
    bottom: 0;
    left: 285px;

    width: auto !important;

    height: 100vh !important;

    min-width: 0 !important;
    min-height: 100vh !important;

    overflow-x: hidden !important;
    overflow-y: auto !important;

    background:
        linear-gradient(
            135deg,
            #f1f6fc 0%,
            #f7f4ff 50%,
            #f0f8f6 100%
        );

    transition:
        left .25s ease;
}

.campus360-training.sidebar-closed
.c360-training-main {
    left: 0;
}


/* =========================================================
   TOP CAMPUS360 NAVBAR - WHITE
   ========================================================= */

.c360-training-topbar {
    position: sticky;

    top: 0;

    z-index: 200;

    width: 100%;

    height: 78px;
    min-height: 78px;

    padding:
        0
        24px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    background: #ffffff !important;

    border-bottom:
        1px solid #dfe4ec;

    box-shadow:
        0 2px 10px
        rgba(20,39,60,.035);
}

.c360-topbar-left {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 13px;
}


/* =========================================================
   HAMBURGER
   ========================================================= */

.c360-menu-button {
    width: 42px;
    height: 42px;
    min-width: 42px;

    padding: 9px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 4px;

    border:
        1px solid #dce2ea;

    border-radius: 10px;

    background: #ffffff;

    cursor: pointer;

    transition:
        background .18s ease,
        border-color .18s ease;
}

.c360-menu-button:hover {
    background: #f1efff;
    border-color: #bcb5ff;
}

.c360-menu-button span {
    display: block;

    width: 19px;
    height: 2px;

    border-radius: 3px;

    background: #5362ee;
}


/* =========================================================
   PAGE TITLE
   ========================================================= */

.c360-page-heading {
    min-width: 150px;

    display: flex;
    flex-direction: column;
}

.c360-page-heading span {
    color: #673cff;

    font-size: 9px;
    font-weight: 950;
    letter-spacing: 1.6px;
}

.c360-page-heading strong {
    margin-top: 5px;

    color: #172a33;

    font-size: 17px;
    font-weight: 900;
}


/* =========================================================
   TOP RIGHT
   ========================================================= */

.c360-topbar-right {
    margin-left: auto;

    display: flex;
    align-items: center;

    gap: 10px;
}


/* =========================================================
   TOP ICONS
   ========================================================= */

.c360-top-icon {
    position: relative;

    width: 41px;
    height: 41px;
    min-width: 41px;

    display: flex;
    align-items: center;
    justify-content: center;

    border:
        1px solid #dce2ea;

    border-radius: 10px;

    background: #ffffff;

    color: #536476;

    cursor: pointer;

    transition:
        color .18s ease,
        background .18s ease,
        border-color .18s ease;
}

.c360-top-icon:hover {
    color: #673cff;

    border-color: #c9baff;

    background: #f8f5ff;
}

.c360-top-icon svg {
    width: 18px;
    height: 18px;

    fill: none;
    stroke: currentColor;

    stroke-width: 1.8;

    stroke-linecap: round;
    stroke-linejoin: round;
}

.c360-notification-button {
    border-color: #d9ddff;
}

.c360-notification-button svg {
    color: #4f46e5;
}

.c360-notification-dot {
    position: absolute;

    top: 6px;
    right: 6px;

    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: #ff3b4f;

    border:
        1.5px solid #ffffff;
}


/* =========================================================
   TOP PROFILE
   ========================================================= */

.c360-top-profile {
    min-height: 45px;

    padding-left: 11px;

    display: flex;
    align-items: center;

    gap: 9px;

    border-left:
        1px solid #e0e4eb;

    color: inherit !important;
    text-decoration: none !important;
}

.c360-top-avatar {
    width: 39px;
    height: 39px;
    min-width: 39px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background:
        linear-gradient(
            135deg,
            #7659f4,
            #6654eb
        );

    color: #ffffff;

    font-size: 11px;
    font-weight: 900;
}

.c360-top-profile-info {
    min-width: 0;

    display: flex;
    flex-direction: column;
}

.c360-top-profile-info strong {
    display: block;

    max-width: 190px;

    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;

    color: #101828;

    font-size: 12px;
    font-weight: 900;
}

.c360-top-profile-info span {
    display: block;

    margin-top: 2px;

    color: #667085;

    font-size: 9px;
    font-weight: 600;
}

.c360-profile-chevron {
    color: #667085;
    font-size: 13px;
}


/* =========================================================
   TRAINING CONTENT
   ========================================================= */

.c360-training-content {
    width: 100% !important;

    min-width: 0;

    margin: 0 !important;

    /*
       Important:
       Creates clear separation between white navbar
       and light-purple Training hero card.
    */
    padding:
        24px
        15px
        55px;

    background: transparent;
}


/* =========================================================
   TRAINING HERO / TRAINING CARD
   LIGHT PURPLE
   ========================================================= */

.c360-header {
    position: relative;

    z-index: 1;

    width: 100%;

    min-height: 178px;

    margin: 0;

    padding:
        30px
        38px;

    display: flex;
    align-items: center;

    border-radius: 18px;

    background: #D7BCFC !important;

    border:
        1px solid #c6a5f3;

    box-shadow:
        0 15px 35px
        rgba(88,55,145,.12);
}

.c360-header-left {
    min-width: 0;
    flex: 1;
}

.c360-eyebrow {
    margin-bottom: 9px;

    color: #5b21b6;

    font-size: 13px;
    font-weight: 850;

    letter-spacing: 1.5px;
}

.c360-header h1 {
    margin: 0;

    color: #24133f;

    font-size: 42px;

    line-height: 1.1;

    font-weight: 850;

    letter-spacing: -.8px;
}

.c360-header p {
    max-width: 820px;

    margin:
        11px
        0
        0;

    color: #49345f;

    font-size: 17px;

    line-height: 1.55;
}


/* =========================================================
   SUMMARY
   ========================================================= */

.c360-summary-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 17px;

    margin:
        25px
        0
        31px;
}

.c360-summary-card {
    position: relative;

    min-height: 126px;

    padding: 19px;

    display: flex;
    align-items: flex-start;

    gap: 13px;

    overflow: hidden;

    background: #ffffff;

    border:
        1px solid #d8e2ed;

    border-radius: 15px;

    box-shadow:
        0 5px 17px
        rgba(25,43,60,.045);
}

.c360-summary-card::after {
    content: "";

    position: absolute;

    left: 0;
    right: 0;
    bottom: 0;

    height: 4px;
}

.c360-summary-card.purple::after {
    background: #7040ff;
}

.c360-summary-card.blue::after {
    background: #2782e6;
}

.c360-summary-card.green::after {
    background: #16a34a;
}

.c360-summary-card.orange::after {
    background: #dc8b00;
}

.c360-summary-icon {
    width: 40px;
    height: 40px;
    min-width: 40px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 10px;

    font-size: 18px;
    font-weight: 800;
}

.c360-summary-card.purple
.c360-summary-icon {
    color: #7040ff;
    background: #eee7ff;
}

.c360-summary-card.blue
.c360-summary-icon {
    color: #2475d4;
    background: #e1efff;
}

.c360-summary-card.green
.c360-summary-icon {
    color: #15803d;
    background: #dcfce7;
}

.c360-summary-card.orange
.c360-summary-icon {
    color: #c56f00;
    background: #fff0c9;
}

.c360-summary-label {
    display: block;

    color: #637188;

    font-size: 11px;
    font-weight: 850;

    letter-spacing: 1px;
}

.c360-summary-card strong {
    display: block;

    margin-top: 7px;

    color: #0d203a;

    font-size: 31px;
    line-height: 1;

    font-weight: 850;
}

.c360-summary-card small {
    display: block;

    margin-top: 7px;

    color: #8290a4;

    font-size: 12px;
}


/* =========================================================
   GENERAL SECTION
   ========================================================= */

.c360-section {
    width: 100%;

    min-width: 0;

    margin-bottom: 36px;
}

.c360-section-header {
    margin-bottom: 14px;

    display: flex;
    align-items: flex-end;
    justify-content: space-between;

    gap: 15px;
}

.c360-section-eyebrow {
    display: block;

    margin-bottom: 6px;

    color: #4f46e5;

    font-size: 11px;
    font-weight: 900;

    letter-spacing: 1.2px;
}

.c360-section-header h2 {
    margin: 0;

    color: #0a1d38;

    font-size: 25px;
    font-weight: 850;
}

.c360-section-header p {
    margin:
        6px
        0
        0;

    color: #687a91;

    font-size: 14px;
}

.c360-readonly-badge {
    flex-shrink: 0;

    padding:
        8px
        12px;

    border:
        1px solid #dbe3ed;

    border-radius: 20px;

    background: #ffffff;

    color: #64748b;

    font-size: 11px;
    font-weight: 800;
}


/* =========================================================
   TRAINING LIST / CARDS
   ========================================================= */

.c360-training-list {
    width: 100%;

    display: flex;
    flex-direction: column;

    gap: 13px;
}

.c360-training-card {
    width: 100%;

    min-width: 0;

    padding: 19px;

    background: #ffffff;

    border:
        1px solid #d8e2ed;

    border-radius: 15px;

    box-shadow:
        0 5px 17px
        rgba(25,43,60,.045);
}

.c360-training-top {
    display: flex;

    align-items: flex-start;
    justify-content: space-between;

    gap: 20px;

    padding-bottom: 16px;

    border-bottom:
        1px solid #e8edf4;
}

.c360-training-id {
    display: block;

    margin-bottom: 5px;

    color: #7040ff;

    font-size: 11px;
    font-weight: 900;

    letter-spacing: 1px;
}

.c360-training-top h3 {
    margin: 0;

    color: #0a1d38;

    font-size: 22px;
    font-weight: 850;
}

.c360-skill-badge {
    display: inline-flex;

    margin-top: 8px;

    padding:
        5px
        9px;

    border:
        1px solid #c7d2fe;

    border-radius: 20px;

    background: #eef2ff;

    color: #4338ca;

    font-size: 11px;
    font-weight: 800;
}

.c360-status {
    flex-shrink: 0;

    padding:
        6px
        10px;

    border-radius: 20px;

    font-size: 10px;
    font-weight: 900;
}

.c360-status.status-completed {
    color: #087d4b;
    background: #dcfce7;
}

.c360-status.status-in-progress,
.c360-status.status-ongoing {
    color: #1d4ed8;
    background: #dbeafe;
}

.c360-status.status-enrolled {
    color: #6d28d9;
    background: #ede9fe;
}

.c360-status.status-pending,
.c360-status.status-not-started {
    color: #b45309;
    background: #fef3c7;
}


/* =========================================================
   TRAINING DETAILS
   ========================================================= */

.c360-training-details {
    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 11px;

    margin-top: 17px;
}

.c360-detail-item {
    min-width: 0;

    padding: 12px;

    border:
        1px solid #e2e8f0;

    border-radius: 10px;

    background: #f8fafc;
}

.c360-detail-item span {
    display: block;

    margin-bottom: 5px;

    color: #667085;

    font-size: 9px;
    font-weight: 900;

    letter-spacing: .7px;
}

.c360-detail-item strong {
    display: block;

    color: #172033;

    font-size: 13px;
    font-weight: 850;

    word-break: break-word;
}

.c360-detail-item small {
    display: block;

    margin-top: 3px;

    color: #8a97a8;

    font-size: 10px;
}


/* =========================================================
   TRAINING PROGRESS
   ========================================================= */

.c360-progress-area {
    margin-top: 15px;

    padding: 13px;

    border:
        1px solid #e2e8f0;

    border-radius: 10px;

    background: #f8fafc;
}

.c360-progress-heading {
    display: flex;

    align-items: center;
    justify-content: space-between;

    gap: 12px;

    margin-bottom: 8px;
}

.c360-progress-heading span {
    color: #475569;

    font-size: 11px;
    font-weight: 750;
}

.c360-progress-heading strong {
    color: #172033;

    font-size: 12px;
    font-weight: 900;
}

.c360-progress-track {
    width: 100%;

    height: 7px;

    overflow: hidden;

    border-radius: 20px;

    background: #e2e8f0;
}

.c360-progress-track.small {
    height: 6px;
}

.c360-progress-fill {
    height: 100%;

    border-radius: 20px;

    background:
        linear-gradient(
            90deg,
            #4f46e5,
            #6366f1
        );
}

.c360-score-grid {
    display: grid;

    grid-template-columns:
        repeat(3,minmax(0,1fr));

    gap: 10px;

    margin-top: 12px;
}

.c360-score-box {
    min-width: 0;

    padding: 12px;

    border:
        1px solid #e2e8f0;

    border-radius: 9px;

    background: #ffffff;
}

.c360-score-box span {
    display: block;

    color: #667085;

    font-size: 8px;
    font-weight: 900;

    letter-spacing: .8px;
}

.c360-score-box strong {
    display: block;

    margin-top: 5px;

    color: #172033;

    font-size: 13px;
    font-weight: 850;

    word-break: break-word;
}

.c360-score-box.score-highlight {
    border-color: #fed7aa;

    background: #fffaf0;
}

.c360-score-box.score-highlight strong {
    color: #c2410c;

    font-size: 17px;
}

.muted-score {
    color: #94a3b8 !important;

    font-size: 11px !important;
}


/* =========================================================
   TWO COLUMN
   ========================================================= */

.c360-two-column {
    width: 100%;

    min-width: 0;

    display: grid;

    grid-template-columns:
        minmax(0,1fr)
        minmax(0,1fr);

    gap: 17px;

    margin-bottom: 36px;
}

.c360-panel {
    min-width: 0;

    width: 100%;

    padding: 19px;

    border:
        1px solid #d8e2ed;

    border-radius: 15px;

    background: #ffffff;

    box-shadow:
        0 5px 17px
        rgba(25,43,60,.045);
}

.c360-panel-header {
    padding-bottom: 13px;

    border-bottom:
        1px solid #e8edf4;
}

.c360-panel-header h2 {
    margin: 0;

    color: #0a1d38;

    font-size: 21px;
    font-weight: 850;
}

.c360-panel-header p {
    margin:
        5px
        0
        0;

    color: #687a91;

    font-size: 12px;
}


/* =========================================================
   PROGRESS LIST
   ========================================================= */

.c360-progress-list {
    display: flex;
    flex-direction: column;

    gap: 13px;

    margin-top: 16px;
}

.c360-progress-row {
    padding-bottom: 12px;

    border-bottom:
        1px solid #edf1f5;
}

.c360-progress-row:last-child {
    padding-bottom: 0;
    border-bottom: 0;
}

.c360-progress-row-head {
    display: flex;

    align-items: center;
    justify-content: space-between;

    gap: 15px;

    margin-bottom: 7px;
}

.c360-progress-row-head strong {
    color: #172033;

    font-size: 13px;
    font-weight: 850;
}

.c360-progress-row-head span {
    display: block;

    margin-top: 3px;

    color: #64748b;

    font-size: 10px;
}

.c360-progress-status {
    display: inline-block;

    margin-top: 5px;

    color: #64748b;

    font-size: 10px;
    font-weight: 700;
}

.c360-panel-empty {
    padding:
        30px
        10px;

    text-align: center;

    color: #94a3b8;

    font-size: 12px;
}


/* =========================================================
   ASSESSMENT HEADER
   ========================================================= */

.c360-assessment-panel-header {
    display: flex;

    align-items: flex-start;
    justify-content: space-between;

    gap: 15px;
}

.c360-assessment-title-click {
    min-width: 0;
    cursor: pointer;
}

.c360-assessment-click-hint {
    display: block;

    margin-top: 6px;

    color: #6366f1;

    font-size: 9px;
    font-weight: 750;
}

.c360-assessment-header-actions {
    display: flex;

    align-items: center;

    gap: 10px;

    flex-shrink: 0;
}

.c360-large-score {
    color: #4338ca;

    font-size: 27px;
    line-height: 1;

    font-weight: 900;

    text-align: right;
}

.c360-large-score span {
    display: block;

    margin-top: 4px;

    color: #94a3b8;

    font-size: 9px;
    font-weight: 700;
}

.c360-large-score.empty {
    color: #94a3b8;
}

.c360-assessment-view-button {
    min-height: 35px;

    padding:
        0
        10px;

    display: inline-flex;
    align-items: center;

    gap: 6px;

    border:
        1px solid #c7d2fe;

    border-radius: 8px;

    background: #ffffff;

    color: #4338ca;

    font-family: inherit;

    font-size: 10px;
    font-weight: 850;

    cursor: pointer;
}


/* =========================================================
   ASSESSMENT LIST
   ========================================================= */

.c360-assessment-list {
    display: flex;
    flex-direction: column;

    gap: 7px;

    margin-top: 15px;
}

.c360-assessment-row-button {
    width: 100%;

    padding: 10px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 12px;

    border:
        1px solid #e2e8f0;

    border-radius: 9px;

    background: #f8fafc;

    font-family: inherit;

    text-align: left;

    cursor: pointer;
}

.c360-assessment-row-button:hover,
.c360-assessment-row-button.is-selected {
    border-color: #c4b5fd;

    background: #f6f3ff;
}

.c360-assessment-main {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 9px;
}

.c360-assessment-icon {
    width: 32px;
    height: 32px;
    min-width: 32px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 8px;

    background: #ede9fe;

    color: #5b21b6;

    font-size: 13px;
}

.c360-assessment-copy {
    min-width: 0;
}

.c360-assessment-copy strong {
    display: block;

    overflow: hidden;

    white-space: nowrap;
    text-overflow: ellipsis;

    color: #172033;

    font-size: 12px;
    font-weight: 850;
}

.c360-assessment-copy span {
    display: block;

    margin-top: 2px;

    color: #94a3b8;

    font-size: 9px;
}

.c360-assessment-meta {
    display: flex;

    align-items: center;

    gap: 7px;

    flex-shrink: 0;
}

.c360-assessment-status {
    padding:
        4px
        7px;

    border-radius: 12px;

    background: #eef2ff;

    color: #4338ca;

    font-size: 8px;
    font-weight: 850;
}

.c360-assessment-score {
    min-width: 53px;

    padding:
        5px
        6px;

    border-radius: 7px;

    text-align: center;

    font-size: 10px;
    font-weight: 900;
}

.score-high {
    background: #dcfce7;
    color: #15803d;
}

.score-medium {
    background: #fef3c7;
    color: #b45309;
}

.score-low {
    background: #fee2e2;
    color: #b91c1c;
}

.score-pending {
    background: #f1f5f9;
    color: #64748b;
}

.c360-assessment-arrow {
    color: #94a3b8;
}


/* =========================================================
   ASSESSMENT DETAILS
   ========================================================= */

.c360-assessment-details {
    margin-top: 15px;

    padding: 16px;

    border:
        1px solid #ddd6fe;

    border-radius: 12px;

    background:
        linear-gradient(
            135deg,
            #fbfaff 0%,
            #f3f0ff 100%
        );
}

.c360-assessment-details-header {
    display: flex;

    align-items: flex-start;
    justify-content: space-between;

    gap: 15px;

    padding-bottom: 13px;

    border-bottom:
        1px solid #e4ddfb;
}

.c360-assessment-details-header h3 {
    margin:
        4px
        0
        3px;

    color: #111827;

    font-size: 20px;
    font-weight: 900;
}

.c360-assessment-details-header p {
    margin: 0;

    color: #64748b;

    font-size: 11px;
}

.c360-assessment-close {
    width: 30px;
    height: 30px;

    border:
        1px solid #d8d2ef;

    border-radius: 8px;

    background: #ffffff;

    color: #64748b;

    cursor: pointer;
}

.c360-assessment-detail-grid {
    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 8px;

    margin-top: 12px;
}

.c360-assessment-detail-card {
    min-height: 77px;

    padding: 10px;

    border:
        1px solid #e2e8f0;

    border-radius: 9px;

    background: #ffffff;
}

.c360-assessment-detail-card span {
    display: block;

    color: #64748b;

    font-size: 8px;
    font-weight: 900;

    letter-spacing: .7px;
}

.c360-assessment-detail-card strong {
    display: block;

    margin-top: 5px;

    color: #172033;

    font-size: 14px;
    font-weight: 900;
}

.c360-assessment-detail-card small {
    display: block;

    margin-top: 3px;

    color: #7c8798;

    font-size: 9px;
}

.assessment-card-purple {
    background: #faf7ff;
    border-color: #ddd6fe;
}

.assessment-card-blue {
    background: #f7fbff;
    border-color: #bfdbfe;
}

.assessment-card-orange {
    background: #fffaf3;
    border-color: #fed7aa;
}

.assessment-card-green {
    background: #f5fdf8;
    border-color: #bbf7d0;
}

.c360-assessment-detail-columns {
    display: grid;

    grid-template-columns:
        minmax(0,1fr)
        minmax(0,1fr);

    gap: 10px;

    margin-top: 11px;
}

.c360-assessment-description-card,
.c360-attendance-card {
    padding: 12px;

    border:
        1px solid #e2e8f0;

    border-radius: 10px;

    background: #ffffff;
}

.c360-assessment-subheading {
    display: flex;

    align-items: center;

    gap: 6px;

    color: #312e81;

    font-size: 11px;
    font-weight: 850;
}

.c360-assessment-subheading i {
    color: #4f46e5;
}

.c360-assessment-description-card p {
    margin:
        8px
        0
        0;

    color: #475569;

    font-size: 11px;

    line-height: 1.55;
}

.c360-resource-link {
    display: inline-flex;

    align-items: center;

    gap: 5px;

    margin-top: 9px;

    padding:
        6px
        8px;

    border-radius: 7px;

    background: #eef2ff;

    color: #4338ca !important;

    font-size: 9px;
    font-weight: 800;

    text-decoration: none !important;
}

.c360-feedback-note {
    margin-top: 10px;

    padding: 9px;

    border:
        1px solid #e2e8f0;

    border-left:
        3px solid #6366f1;

    border-radius: 7px;

    background: #f8fafc;
}

.c360-feedback-note span {
    display: block;

    color: #64748b;

    font-size: 8px;
    font-weight: 900;

    letter-spacing: .7px;
}

.c360-feedback-note strong {
    display: block;

    margin-top: 3px;

    color: #334155;

    font-size: 10px;

    line-height: 1.45;
}


/* =========================================================
   ATTENDANCE
   ========================================================= */

.c360-attendance-summary-grid {
    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 5px;

    margin-top: 10px;
}

.attendance-stat {
    padding:
        7px
        4px;

    text-align: center;

    border-radius: 7px;
}

.attendance-stat strong {
    display: block;

    color: #172033;

    font-size: 16px;
    font-weight: 900;
}

.attendance-stat span {
    display: block;

    margin-top: 2px;

    color: #64748b;

    font-size: 8px;
    font-weight: 800;
}

.attendance-total {
    background: #f1f5f9;
}

.attendance-present {
    background: #dcfce7;
}

.attendance-present strong {
    color: #15803d;
}

.attendance-late {
    background: #fef3c7;
}

.attendance-late strong {
    color: #b45309;
}

.attendance-absent {
    background: #fee2e2;
}

.attendance-absent strong {
    color: #b91c1c;
}

.c360-attendance-percent-row {
    display: flex;

    align-items: center;
    justify-content: space-between;

    margin-top: 11px;

    color: #526074;

    font-size: 9px;
    font-weight: 750;
}

.c360-attendance-percent-row strong {
    color: #111827;

    font-size: 14px;
    font-weight: 900;
}

.attendance-progress {
    margin-top: 6px;
}


/* =========================================================
   ATTENDANCE HISTORY
   ========================================================= */

.c360-attendance-history {
    margin-top: 11px;

    padding: 11px;

    border:
        1px solid #e2e8f0;

    border-radius: 9px;

    background: #ffffff;
}

.c360-attendance-history-list {
    margin-top: 8px;

    display: flex;
    flex-direction: column;

    gap: 5px;
}

.c360-attendance-history-row {
    display: grid;

    grid-template-columns:
        100px
        90px
        minmax(0,1fr);

    gap: 8px;

    align-items: center;

    padding: 7px;

    border:
        1px solid #edf1f5;

    border-radius: 7px;

    background: #f8fafc;
}

.attendance-history-date {
    color: #334155;

    font-size: 9px;
    font-weight: 800;
}

.attendance-history-status {
    display: inline-flex;

    justify-content: center;

    padding:
        4px
        6px;

    border-radius: 13px;

    font-size: 8px;
    font-weight: 850;
}

.attendance-status-present {
    color: #15803d;
    background: #dcfce7;
}

.attendance-status-late {
    color: #b45309;
    background: #fef3c7;
}

.attendance-status-absent {
    color: #b91c1c;
    background: #fee2e2;
}

.attendance-history-remarks {
    overflow: hidden;

    color: #64748b;

    font-size: 9px;
    font-weight: 600;

    white-space: nowrap;
    text-overflow: ellipsis;
}

.c360-assessment-no-attendance {
    margin-top: 10px;

    padding: 10px;

    border:
        1px dashed #cbd5e1;

    border-radius: 8px;

    background: #f8fafc;

    color: #64748b;

    text-align: center;

    font-size: 10px;
    font-weight: 700;
}


/* =========================================================
   TRAINER PERFORMANCE
   ========================================================= */

.c360-interview-count {
    min-width: 80px;

    padding:
        8px
        11px;

    text-align: center;

    border:
        1px solid #c7d2fe;

    border-radius: 10px;

    background: #eef2ff;
}

.c360-interview-count strong {
    display: block;

    color: #4338ca;

    font-size: 20px;
}

.c360-interview-count span {
    display: block;

    margin-top: 2px;

    color: #64748b;

    font-size: 9px;
}

.c360-trainer-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(3,minmax(0,1fr));

    gap: 15px;
}

.c360-trainer-card {
    min-width: 0;

    padding: 17px;

    border:
        1px solid #d8e2ed;

    border-radius: 14px;

    background: #ffffff;

    box-shadow:
        0 5px 16px
        rgba(25,43,60,.045);
}

.c360-trainer-header {
    display: flex;

    align-items: center;

    gap: 10px;

    padding-bottom: 12px;

    border-bottom:
        1px solid #edf1f5;
}

.c360-trainer-avatar {
    width: 42px;
    height: 42px;
    min-width: 42px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background:
        linear-gradient(
            135deg,
            #e0e7ff,
            #c7d2fe
        );

    color: #3730a3;

    font-size: 14px;
    font-weight: 850;
}

.c360-trainer-name {
    min-width: 0;
}

.c360-trainer-name span {
    display: block;

    color: #94a3b8;

    font-size: 8px;
    font-weight: 900;

    letter-spacing: 1px;
}

.c360-trainer-name h3 {
    margin:
        3px
        0
        0;

    overflow: hidden;

    color: #172033;

    font-size: 15px;
    font-weight: 850;

    white-space: nowrap;
    text-overflow: ellipsis;
}

.c360-trainer-name small {
    display: block;

    margin-top: 2px;

    color: #64748b;

    font-size: 9px;
}

.c360-trainer-metrics {
    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 5px;

    margin-top: 12px;
}

.c360-trainer-metrics > div {
    padding:
        7px
        3px;

    text-align: center;

    border:
        1px solid #e8edf3;

    border-radius: 7px;

    background: #f8fafc;
}

.c360-trainer-metrics strong {
    display: block;

    color: #172033;

    font-size: 14px;
    font-weight: 900;
}

.c360-trainer-metrics span {
    display: block;

    margin-top: 2px;

    color: #94a3b8;

    font-size: 7px;
    line-height: 1.2;
}

.c360-trainer-score-summary {
    margin-top: 12px;

    padding: 10px;

    border:
        1px solid #e2e8f0;

    border-radius: 8px;

    background: #f8fafc;
}

.c360-score-line {
    display: grid;

    grid-template-columns:
        82px
        minmax(0,1fr)
        38px;

    align-items: center;

    gap: 6px;

    margin-bottom: 8px;
}

.c360-score-line:last-child {
    margin-bottom: 0;
}

.c360-score-line > span {
    color: #475569;

    font-size: 8px;
    font-weight: 750;
}

.c360-mini-track {
    width: 100%;

    height: 5px;

    overflow: hidden;

    border-radius: 20px;

    background: #e2e8f0;
}

.c360-mini-fill {
    height: 100%;

    border-radius: 20px;

    background:
        linear-gradient(
            90deg,
            #4f46e5,
            #6366f1
        );
}

.c360-score-line > strong {
    color: #334155;

    font-size: 9px;

    text-align: right;
}

.c360-view-trainer-btn {
    width: 100%;

    margin-top: 12px;

    padding:
        9px
        10px;

    display: flex;

    align-items: center;
    justify-content: space-between;

    border:
        1px solid #c7d2fe;

    border-radius: 8px;

    background: #eef2ff;

    color: #4338ca;

    font-size: 10px;
    font-weight: 850;

    cursor: pointer;
}

.c360-view-trainer-btn:hover {
    background: #e0e7ff;
}


/* =========================================================
   EMPTY
   ========================================================= */

.c360-empty {
    width: 100%;

    padding:
        45px
        20px;

    text-align: center;

    border:
        1px dashed #cbd5e1;

    border-radius: 15px;

    background: #ffffff;
}

.c360-empty-icon {
    width: 45px;
    height: 45px;

    margin:
        0
        auto
        12px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #eef2ff;

    color: #4f46e5;

    font-size: 19px;
}

.c360-empty h3 {
    margin: 0;

    color: #334155;

    font-size: 18px;
    font-weight: 800;
}

.c360-empty p {
    max-width: 550px;

    margin:
        7px
        auto
        0;

    color: #64748b;

    font-size: 12px;
    line-height: 1.6;
}


/* =========================================================
   MODALS
   ========================================================= */

.c360-modal-backdrop {
    position: fixed;
    inset: 0;

    z-index: 90000;

    padding: 20px;

    display: flex;

    align-items: center;
    justify-content: center;

    background:
        rgba(15,23,42,.62);
}

.c360-modal {
    position: relative;

    width: 100%;

    max-width: 900px;

    max-height: 90vh;

    overflow-y: auto;

    border-radius: 18px;

    background: #ffffff;

    box-shadow:
        0 30px 80px
        rgba(0,0,0,.25);
}

.c360-modal-header {
    padding:
        23px
        26px;

    display: flex;

    align-items: flex-start;
    justify-content: space-between;

    gap: 20px;

    border-bottom:
        1px solid #e5eaf1;
}

.c360-modal-person {
    display: flex;

    align-items: center;

    gap: 12px;
}

.c360-modal-avatar {
    width: 47px;
    height: 47px;
    min-width: 47px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background:
        linear-gradient(
            135deg,
            #6366f1,
            #4338ca
        );

    color: #ffffff;

    font-size: 15px;
    font-weight: 850;
}

.c360-modal-header span,
.c360-modal-eyebrow {
    display: block;

    color: #4f46e5;

    font-size: 9px;
    font-weight: 900;

    letter-spacing: 1px;
}

.c360-modal-header h2 {
    margin:
        4px
        0
        0;

    color: #172033;

    font-size: 23px;
    font-weight: 850;
}

.c360-modal-header small {
    display: block;

    margin-top: 3px;

    color: #64748b;

    font-size: 10px;
}

.c360-close-btn {
    width: 34px;
    height: 34px;
    min-width: 34px;

    display: flex;

    align-items: center;
    justify-content: center;

    border: 0;

    border-radius: 50%;

    background: #f1f5f9;

    color: #64748b;

    font-size: 23px;

    cursor: pointer;
}

.c360-modal-stats {
    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 9px;

    padding:
        18px
        26px;

    background: #f8fafc;

    border-bottom:
        1px solid #e5eaf1;
}

.c360-modal-stats > div {
    padding: 11px;

    text-align: center;

    border:
        1px solid #e2e8f0;

    border-radius: 9px;

    background: #ffffff;
}

.c360-modal-stats strong {
    display: block;

    color: #172033;

    font-size: 20px;
}

.c360-modal-stats span {
    display: block;

    margin-top: 3px;

    color: #64748b;

    font-size: 9px;
}

.c360-modal-section {
    padding:
        20px
        26px;

    border-bottom:
        1px solid #e8edf3;
}

.c360-modal-section:last-child {
    border-bottom: 0;
}

.c360-modal-section-title {
    display: flex;

    align-items: center;
    justify-content: space-between;

    margin-bottom: 12px;
}

.c360-modal-section-title > span {
    color: #475569;

    font-size: 10px;
    font-weight: 900;

    letter-spacing: 1px;
}

.c360-modal-section-title > strong {
    width: 24px;
    height: 24px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #eef2ff;

    color: #4338ca;

    font-size: 10px;
}

.c360-interview-list {
    display: flex;

    flex-direction: column;

    gap: 7px;
}

.c360-interview-row {
    display: grid;

    grid-template-columns:
        36px
        minmax(0,1fr)
        auto;

    align-items: center;

    gap: 10px;

    padding: 10px;

    border:
        1px solid #e2e8f0;

    border-radius: 8px;

    background: #f8fafc;
}

.c360-interview-icon {
    width: 36px;
    height: 36px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 9px;

    background: #eef2ff;

    color: #4338ca;

    font-size: 12px;
    font-weight: 850;
}

.c360-interview-info {
    min-width: 0;
}

.c360-interview-info strong {
    display: block;

    color: #1e293b;

    font-size: 12px;
}

.c360-interview-info span {
    display: block;

    margin-top: 2px;

    color: #64748b;

    font-size: 10px;
}

.c360-interview-info small {
    display: block;

    margin-top: 3px;

    color: #94a3b8;

    font-size: 9px;
}

.c360-interview-status {
    text-align: right;
}

.c360-interview-badge {
    display: inline-flex;

    padding:
        4px
        7px;

    border-radius: 14px;

    font-size: 9px;
    font-weight: 850;
}

.c360-interview-badge.present {
    color: #15803d;
    background: #dcfce7;
}

.c360-interview-badge.scheduled {
    color: #b45309;
    background: #fef3c7;
}

.c360-interview-status small {
    display: block;

    margin-top: 3px;

    color: #94a3b8;

    font-size: 9px;
}


/* =========================================================
   FEEDBACK MODAL
   ========================================================= */

.c360-feedback-list {
    display: flex;

    flex-direction: column;

    gap: 7px;
}

.c360-feedback-row {
    width: 100%;

    display: grid;

    grid-template-columns:
        72px
        minmax(0,1fr)
        50px
        18px;

    align-items: center;

    gap: 10px;

    padding: 10px;

    text-align: left;

    border:
        1px solid #e2e8f0;

    border-radius: 8px;

    background: #f8fafc;

    cursor: pointer;
}

.c360-feedback-row:hover {
    background: #f1f5f9;
}

.c360-feedback-date {
    color: #64748b;

    font-size: 9px;
}

.c360-feedback-main {
    min-width: 0;
}

.c360-feedback-main strong {
    display: block;

    color: #1e293b;

    font-size: 11px;
}

.c360-feedback-main > span {
    display: block;

    margin-top: 2px;

    color: #94a3b8;

    font-size: 9px;
}

.c360-feedback-score-pills {
    display: flex;

    flex-wrap: wrap;

    gap: 4px;

    margin-top: 5px;
}

.c360-feedback-score-pills span {
    padding:
        3px
        5px;

    border-radius: 8px;

    background: #eef2ff;

    color: #4338ca;

    font-size: 8px;
    font-weight: 750;
}

.c360-feedback-overall {
    text-align: center;
}

.c360-feedback-overall strong {
    display: block;

    color: #b45309;

    font-size: 18px;
}

.c360-feedback-overall span {
    display: block;

    margin-top: 2px;

    color: #94a3b8;

    font-size: 8px;
}

.c360-feedback-arrow {
    color: #64748b;

    font-size: 17px;

    text-align: center;
}


/* =========================================================
   FEEDBACK DETAIL
   ========================================================= */

.c360-feedback-detail-score {
    display: grid;

    grid-template-columns:
        140px
        minmax(0,1fr);

    gap: 17px;

    align-items: center;

    padding:
        20px
        26px;

    background: #f8fafc;

    border-bottom:
        1px solid #e5eaf1;
}

.c360-big-score {
    padding: 15px;

    text-align: center;

    border:
        1px solid #fed7aa;

    border-radius: 11px;

    background: #fff7ed;
}

.c360-big-score strong {
    display: block;

    color: #c2410c;

    font-size: 35px;

    line-height: 1;
}

.c360-big-score span {
    display: block;

    margin-top: 5px;

    color: #9a3412;

    font-size: 9px;
    font-weight: 800;
}

.c360-detail-score-grid {
    display: grid;

    grid-template-columns:
        repeat(3,minmax(0,1fr));

    gap: 8px;
}

.c360-detail-score-grid > div {
    padding: 11px;

    text-align: center;

    border:
        1px solid #e2e8f0;

    border-radius: 9px;

    background: #ffffff;
}

.c360-detail-score-grid span {
    display: block;

    color: #64748b;

    font-size: 9px;
}

.c360-detail-score-grid strong {
    display: block;

    margin-top: 5px;

    color: #4338ca;

    font-size: 20px;
}

.c360-feedback-detail-grid {
    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 8px;

    padding:
        20px
        26px;
}

.c360-detail-block {
    padding: 11px;

    border:
        1px solid #e2e8f0;

    border-radius: 9px;

    background: #f8fafc;
}

.c360-detail-block span {
    display: block;

    color: #64748b;

    font-size: 8px;
    font-weight: 900;
}

.c360-detail-block strong {
    display: block;

    margin-top: 4px;

    color: #1e293b;

    font-size: 11px;
}

.c360-detail-block small {
    display: block;

    margin-top: 2px;

    color: #94a3b8;

    font-size: 9px;
}

.c360-text-detail {
    padding:
        0
        26px
        20px;
}

.c360-text-detail > div {
    padding:
        13px
        0;

    border-top:
        1px solid #e8edf3;
}

.c360-text-detail > div:first-child {
    border-top: 0;
}

.c360-text-detail span {
    display: block;

    margin-bottom: 6px;

    color: #475569;

    font-size: 9px;
    font-weight: 900;

    letter-spacing: .8px;
}

.c360-text-detail p {
    margin: 0;

    color: #334155;

    font-size: 11px;

    line-height: 1.6;

    white-space: pre-wrap;
}

.c360-text-detail p.not-recorded {
    color: #94a3b8;

    font-style: italic;
}

.c360-modal-footer {
    padding:
        13px
        26px;

    display: flex;

    justify-content: flex-end;

    gap: 8px;

    border-top:
        1px solid #e5eaf1;
}

.c360-primary-btn {
    min-height: 38px;

    padding:
        0
        15px;

    border:
        1px solid #4f46e5;

    border-radius: 8px;

    background: #4f46e5;

    color: #ffffff;

    font-size: 11px;
    font-weight: 850;

    cursor: pointer;
}

.c360-small-empty {
    padding:
        22px
        10px;

    color: #94a3b8;

    text-align: center;

    font-size: 11px;
}


/* =========================================================
   MOBILE / TABLET SIDEBAR
   ========================================================= */

@media (max-width: 900px) {

    .c360-student-sidebar {
        position: fixed !important;

        width: 285px !important;
        min-width: 285px !important;
        max-width: 285px !important;

        transform:
            translateX(-105%);

        box-shadow:
            8px 0 25px
            rgba(25,43,60,.30);
    }

    .campus360-training.sidebar-open
    .c360-student-sidebar {
        transform:
            translateX(0);
    }

    .campus360-training.sidebar-closed
    .c360-student-sidebar {
        transform:
            translateX(-105%);
    }

    .c360-sidebar-overlay {
        position: fixed;

        inset: 0;

        z-index: 90;

        display: block;

        background:
            rgba(15,28,45,.35);
    }

    .campus360-training.sidebar-closed
    .c360-sidebar-overlay {
        display: none;
    }

    .c360-training-main {
        left: 0 !important;

        width: 100vw !important;
    }

    .c360-summary-grid {
        grid-template-columns:
            repeat(2,minmax(0,1fr));
    }

    .c360-two-column {
        grid-template-columns: 1fr;
    }

    .c360-trainer-grid {
        grid-template-columns:
            repeat(2,minmax(0,1fr));
    }

    .c360-training-details {
        grid-template-columns:
            repeat(2,minmax(0,1fr));
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

    .c360-training-topbar {
        height: 68px;
        min-height: 68px;

        padding:
            0
            11px;
    }

    .c360-page-heading {
        display: none;
    }

    .c360-top-profile-info,
    .c360-profile-chevron {
        display: none;
    }

    .c360-top-profile {
        padding-left: 3px;
    }

    .c360-topbar-right {
        gap: 5px;
    }

    .c360-top-icon {
        width: 37px;
        height: 37px;
        min-width: 37px;
    }

    .c360-top-avatar {
        width: 37px;
        height: 37px;
        min-width: 37px;
    }

    .c360-training-content {
        padding:
            16px
            10px
            45px;
    }

    .c360-header {
        min-height: 160px;

        padding:
            25px
            22px;

        border-radius: 16px;
    }

    .c360-header h1 {
        font-size: 31px;
    }

    .c360-header p {
        font-size: 14px;
    }

    .c360-summary-grid {
        grid-template-columns: 1fr;
    }

    .c360-section-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .c360-training-top {
        flex-direction: column;
    }

    .c360-status {
        align-self: flex-start;
    }

    .c360-training-details {
        grid-template-columns: 1fr;
    }

    .c360-score-grid {
        grid-template-columns: 1fr;
    }

    .c360-trainer-grid {
        grid-template-columns: 1fr;
    }

    .c360-assessment-panel-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .c360-assessment-header-actions {
        width: 100%;

        justify-content:
            space-between;
    }

    .c360-assessment-detail-grid {
        grid-template-columns: 1fr;
    }

    .c360-assessment-detail-columns {
        grid-template-columns: 1fr;
    }

    .c360-feedback-detail-score {
        grid-template-columns: 1fr;

        padding:
            18px
            16px;
    }

    .c360-feedback-detail-grid {
        grid-template-columns: 1fr;

        padding:
            18px
            16px;
    }

    .c360-text-detail {
        padding:
            0
            16px
            18px;
    }

    .c360-modal-section {
        padding:
            18px
            16px;
    }

    .c360-modal-header {
        padding:
            18px
            16px;
    }

    .c360-modal-stats {
        grid-template-columns:
            repeat(2,minmax(0,1fr));

        padding: 15px;
    }

    .c360-attendance-history-row {
        grid-template-columns:
            1fr
            1fr;
    }

    .attendance-history-remarks {
        grid-column:
            1 / -1;
    }
}


/* =========================================================
   VERY SMALL SCREEN
   ========================================================= */

@media (max-width: 430px) {

    .c360-training-topbar {
        height: 62px;
        min-height: 62px;
    }

    .c360-menu-button {
        width: 37px;
        height: 37px;
        min-width: 37px;
    }

    .c360-menu-button span {
        width: 17px;
    }

    .c360-header h1 {
        font-size: 28px;
    }

    .c360-panel {
        padding: 15px;
    }

    .c360-training-card {
        padding: 15px;
    }

    .c360-trainer-metrics {
        grid-template-columns:
            repeat(2,minmax(0,1fr));
    }

    .c360-score-line {
        grid-template-columns:
            75px
            minmax(0,1fr)
            35px;
    }

    .c360-feedback-row {
        grid-template-columns:
            1fr
            auto;
    }

    .c360-feedback-date {
        grid-column:
            1 / -1;
    }

    .c360-feedback-arrow {
        display: none;
    }
}


/* =========================================================
   EDIT + PREVIEW PAGE OVERRIDE
   ========================================================= */

.c360-edit-page,
.c360-preview-page {
    width: 100%;

    min-height: 100%;

    padding:
        28px
        32px
        45px;

    background: #f5f7fb;

    color: #172033;
}


/* =========================================================
   PAGE HEADER
   ========================================================= */

.c360-edit-page .page-header,
.c360-preview-page .page-header {
    display: flex;

    align-items: center;
    justify-content: space-between;

    gap: 20px;

    margin-bottom: 24px;
}

.c360-edit-page .page-title,
.c360-preview-page .page-title {
    margin: 0;

    color: #111827;

    font-size: 28px;
    font-weight: 800;
}

.c360-edit-page .page-subtitle,
.c360-preview-page .page-subtitle {
    margin:
        6px
        0
        0;

    color: #667085;

    font-size: 13px;
}


/* =========================================================
   EDIT PAGE
   ========================================================= */

.c360-edit-page {
    background:
        linear-gradient(
            135deg,
            #f5f7ff 0%,
            #f8fafc 55%,
            #f4f9f8 100%
        );
}

.c360-edit-page .edit-header {
    padding:
        22px
        25px;

    margin-bottom: 22px;

    border:
        1px solid #e1e5ef;

    border-radius: 16px;

    background: #ffffff;

    box-shadow:
        0 5px 18px
        rgba(20,35,60,.05);
}

.c360-edit-page .edit-workspace {
    display: grid;

    grid-template-columns:
        minmax(0,1fr)
        330px;

    gap: 20px;

    align-items: start;
}

.c360-edit-page .editor-panel {
    min-width: 0;

    padding: 22px;

    border:
        1px solid #e0e5ee;

    border-radius: 16px;

    background: #ffffff;

    box-shadow:
        0 5px 18px
        rgba(20,35,60,.05);
}

.c360-edit-page .editor-section {
    margin-bottom: 20px;

    padding: 18px;

    border:
        1px solid #e5e9f0;

    border-radius: 12px;

    background: #fafbfc;
}

.c360-edit-page .editor-section:last-child {
    margin-bottom: 0;
}

.c360-edit-page .editor-section h3 {
    margin:
        0
        0
        13px;

    color: #172033;

    font-size: 15px;
    font-weight: 800;
}

.c360-edit-page .form-grid {
    display: grid;

    grid-template-columns:
        repeat(2,minmax(0,1fr));

    gap: 14px;
}

.c360-edit-page .form-group {
    min-width: 0;
}

.c360-edit-page .form-group.full-width {
    grid-column:
        1 / -1;
}

.c360-edit-page label {
    display: block;

    margin-bottom: 6px;

    color: #475467;

    font-size: 11px;
    font-weight: 750;
}

.c360-edit-page input,
.c360-edit-page select,
.c360-edit-page textarea {
    width: 100%;

    padding:
        10px
        12px;

    border:
        1px solid #d8dee8;

    border-radius: 9px;

    background: #ffffff;

    color: #172033;

    font-family: inherit;

    font-size: 13px;

    outline: none;

    transition: .18s ease;
}

.c360-edit-page textarea {
    min-height: 90px;
    resize: vertical;
}

.c360-edit-page input:focus,
.c360-edit-page select:focus,
.c360-edit-page textarea:focus {
    border-color: #6366f1;

    box-shadow:
        0
        0
        0
        3px
        rgba(99,102,241,.10);
}


/* =========================================================
   EDIT SIDEBAR
   ========================================================= */

.c360-edit-page .edit-sidebar {
    position: sticky;

    top: 20px;

    min-width: 0;

    padding: 18px;

    border:
        1px solid #e0e5ee;

    border-radius: 16px;

    background: #ffffff;

    box-shadow:
        0 5px 18px
        rgba(20,35,60,.05);
}

.c360-edit-page .edit-sidebar h3 {
    margin:
        0
        0
        15px;

    color: #172033;

    font-size: 15px;
    font-weight: 800;
}

.c360-edit-page .edit-sidebar-section {
    margin-bottom: 18px;

    padding-bottom: 16px;

    border-bottom:
        1px solid #edf0f4;
}

.c360-edit-page .edit-sidebar-section:last-child {
    margin-bottom: 0;

    padding-bottom: 0;

    border-bottom: 0;
}

.c360-edit-page .option-row {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 12px;

    padding: 9px 0;
}

.c360-edit-page .option-row span {
    color: #475467;

    font-size: 12px;
    font-weight: 650;
}

.c360-edit-page .edit-actions {
    display: flex;

    justify-content: flex-end;

    gap: 10px;

    margin-top: 20px;
}

.c360-edit-page .btn {
    min-height: 38px;

    padding:
        0
        15px;

    border:
        1px solid #d8dee8;

    border-radius: 9px;

    background: #ffffff;

    color: #344054;

    font-family: inherit;

    font-size: 12px;
    font-weight: 800;

    cursor: pointer;
}

.c360-edit-page .btn-primary {
    border-color: #5b50e8;

    background: #5b50e8;

    color: #ffffff;
}

.c360-edit-page .btn-primary:hover {
    background: #493fd0;
}


/* =========================================================
   PREVIEW PAGE
   ========================================================= */

.c360-preview-page {
    background:
        linear-gradient(
            135deg,
            #f4f7fc 0%,
            #f7f4ff 50%,
            #f2f9f7 100%
        );
}

.c360-preview-page .preview-header {
    display: flex;

    align-items: center;
    justify-content: space-between;

    gap: 20px;

    margin-bottom: 20px;

    padding:
        20px
        24px;

    border:
        1px solid #e0e5ee;

    border-radius: 16px;

    background: #ffffff;

    box-shadow:
        0 5px 18px
        rgba(20,35,60,.05);
}

.c360-preview-page .preview-workspace {
    display: grid;

    grid-template-columns:
        minmax(0,1fr)
        300px;

    gap: 20px;

    align-items: start;
}

.c360-preview-page .preview-stage {
    min-height: 650px;

    display: flex;

    align-items: center;
    justify-content: center;

    padding: 30px;

    border:
        1px solid #dfe4ec;

    border-radius: 18px;

    background:
        radial-gradient(
            circle at center,
            #ffffff 0%,
            #eef2f7 70%,
            #e7ebf2 100%
        );

    box-shadow:
        0 8px 25px
        rgba(20,35,60,.06);
}

.c360-preview-page .video-preview {
    position: relative;

    width: 320px;
    height: 570px;

    overflow: hidden;

    border:
        7px solid #172033;

    border-radius: 24px;

    background: #111827;

    box-shadow:
        0 18px 45px
        rgba(15,23,42,.25),
        0 0 0 1px rgba(255,255,255,.7);
}

.c360-preview-page .video-preview video,
.c360-preview-page .video-preview img {
    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;
}

.c360-preview-page .preview-overlay {
    position: absolute;

    inset: 0;

    pointer-events: none;
}

.c360-preview-page .preview-title {
    position: absolute;

    left: 20px;
    right: 20px;
    bottom: 75px;

    color: #ffffff;

    font-size: 21px;
    font-weight: 850;

    text-shadow:
        0
        2px
        8px
        rgba(0,0,0,.4);
}

.c360-preview-page .preview-price {
    position: absolute;

    left: 20px;
    bottom: 45px;

    color: #ffffff;

    font-size: 16px;
    font-weight: 800;

    text-shadow:
        0
        2px
        8px
        rgba(0,0,0,.4);
}

.c360-preview-page .preview-cta {
    position: absolute;

    left: 20px;
    bottom: 15px;

    padding:
        7px
        12px;

    border-radius: 7px;

    background:
        rgba(255,255,255,.92);

    color: #172033;

    font-size: 10px;
    font-weight: 850;
}


/* =========================================================
   PREVIEW INFORMATION PANEL
   ========================================================= */

.c360-preview-page .preview-info {
    min-width: 0;

    padding: 18px;

    border:
        1px solid #e0e5ee;

    border-radius: 16px;

    background: #ffffff;

    box-shadow:
        0 5px 18px
        rgba(20,35,60,.05);
}

.c360-preview-page .preview-info h3 {
    margin:
        0
        0
        15px;

    color: #172033;

    font-size: 15px;
    font-weight: 800;
}

.c360-preview-page .preview-info-card {
    margin-bottom: 10px;

    padding: 12px;

    border:
        1px solid #e5e9f0;

    border-radius: 10px;

    background: #f8fafc;
}

.c360-preview-page .preview-info-card:last-child {
    margin-bottom: 0;
}

.c360-preview-page .preview-info-card span {
    display: block;

    margin-bottom: 4px;

    color: #667085;

    font-size: 9px;
    font-weight: 850;

    letter-spacing: .6px;

    text-transform: uppercase;
}

.c360-preview-page .preview-info-card strong {
    display: block;

    color: #172033;

    font-size: 13px;
    font-weight: 800;

    word-break: break-word;
}

.c360-preview-page .preview-actions {
    display: flex;

    flex-direction: column;

    gap: 9px;

    margin-top: 18px;
}

.c360-preview-page .preview-actions button {
    width: 100%;

    min-height: 40px;

    padding:
        0
        13px;

    border:
        1px solid #d8dee8;

    border-radius: 9px;

    background: #ffffff;

    color: #344054;

    font-family: inherit;

    font-size: 12px;
    font-weight: 800;

    cursor: pointer;
}

.c360-preview-page .preview-actions .primary {
    border-color: #5b50e8;

    background: #5b50e8;

    color: #ffffff;
}

.c360-preview-page .preview-actions .primary:hover {
    background: #493fd0;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

    .c360-edit-page .edit-workspace,
    .c360-preview-page .preview-workspace {
        grid-template-columns: 1fr;
    }

    .c360-edit-page .edit-sidebar,
    .c360-preview-page .preview-info {
        position: static;
    }

    .c360-preview-page .preview-stage {
        min-height: 600px;
    }
}

@media (max-width: 700px) {

    .c360-edit-page,
    .c360-preview-page {
        padding:
            18px
            15px
            35px;
    }

    .c360-edit-page .form-grid {
        grid-template-columns: 1fr;
    }

    .c360-edit-page .form-group.full-width {
        grid-column: auto;
    }

    .c360-preview-page .preview-stage {
        min-height: 520px;
        padding: 20px;
    }

    .c360-preview-page .video-preview {
        width: 270px;
        height: 480px;
    }

    .c360-edit-page .page-title,
    .c360-preview-page .page-title {
        font-size: 23px;
    }
}
/* =========================================================
   FINAL TRAINING HERO
   DARK PURPLE - SAME CAMPUS360 THEME
   ========================================================= */

.campus360-training .c360-header {

    position: relative !important;

    z-index: 1 !important;

    background:
        linear-gradient(
            135deg,
            #241044 0%,
            #351A61 52%,
            #45206D 100%
        ) !important;

    border:
        1px solid #5A357D !important;

    color:
        #FFFFFF !important;

    box-shadow:
        0
        12px
        30px
        rgba(53,26,97,.22) !important;

}


/* Training hero heading */

.campus360-training .c360-header h1,
.campus360-training .c360-header h2 {

    color:
        #FFFFFF !important;

}


/* Training hero paragraph */

.campus360-training .c360-header p {

    color:
        #E5DCF0 !important;

}


/* Training hero eyebrow / small heading */

.campus360-training .c360-header .eyebrow,
.campus360-training .c360-header .c360-eyebrow {

    color:
        #DCCBFF !important;

}


/* Training hero icon / decorative icon */

.campus360-training .c360-header .c360-header-icon,
.campus360-training .c360-header .header-icon {

    background:
        rgba(124,58,237,.18) !important;

    color:
        #C4B5FD !important;

}


/* =========================================================
   KEEP TRAINING SIDEBAR DARK PURPLE
   ========================================================= */

.campus360-training .c360-student-sidebar,
.campus360-training .c360-left-sidebar {

    background:
        linear-gradient(
            180deg,
            #130D2F 0%,
            #160D38 48%,
            #100A29 100%
        ) !important;

    border-right:
        1px solid #2D2157 !important;

}


/* =========================================================
   KEEP TOP CAMPUS360 NAVBAR WHITE
   ========================================================= */

.campus360-training .c360-topbar {

    background:
        #FFFFFF !important;

}


/* =========================================================
   KEEP HERO SEPARATED FROM WHITE NAVBAR
   ========================================================= */

.campus360-training .c360-page-content {

    position:
        relative !important;

    z-index:
        1 !important;

    padding-top:
        24px !important;

}


@media (max-width: 900px) {

    .campus360-training .c360-page-content {

        padding-top:
            18px !important;

    }

}


@media (max-width: 650px) {

    .campus360-training .c360-page-content {

        padding-top:
            14px !important;

    }

}

sp_widget.script:
var TRAINING_TABLE = 'x_snc_campus360_training_program';
var ENROLLMENT_TABLE = 'x_snc_campus360_training_enrollment';
var STUDENT_TABLE = 'x_snc_campus360_student_master';
var TRAINER_TABLE = 'x_snc_campus360_trainer_master';
var MOCK_INTERVIEW_TABLE = 'x_snc_campus360_mock_interview';
var FEEDBACK_TABLE = 'x_snc_campus360_interview_feedback';

var ASSIGNMENT_TABLE = 'x_snc_campus360_assignment';
var SUBMISSION_TABLE = 'x_snc_campus360_assignment_submission';
var ATTENDANCE_TABLE = 'x_snc_campus360_training_attendance';

data.student = null;
data.trainings = [];
data.assessments = [];
data.assessmentDetails = [];
data.trainers = [];
data.totalInterviews = 0;
data.totalFeedbacks = 0;

data.summary = {
    trainingCount: 0,
    inProgress: 0,
    completed: 0,
    avgAssessment: 0,
    hasAssessment: false
};

function isReferenceField(gr, fieldName) {
    if (!fieldName || !gr.isValidField(fieldName)) {
        return false;
    }

    try {
        return gr.getElement(fieldName)
            .getED()
            .getInternalType() == 'reference';
    } catch (e) {
        return false;
    }
}

function value(gr, fieldName) {
    if (!fieldName || !gr.isValidField(fieldName)) {
        return '';
    }

    var v = gr.getValue(fieldName);

    return v === null || v === undefined
        ? ''
        : String(v);
}

function display(gr, fieldName) {
    if (!fieldName || !gr.isValidField(fieldName)) {
        return '';
    }

    var v = gr.getDisplayValue(fieldName);

    return v === null || v === undefined
        ? ''
        : String(v);
}

function numberValue(raw) {
    if (raw === null || raw === undefined || raw === '') {
        return null;
    }

    var n = parseFloat(raw);

    if (isNaN(n)) {
        return null;
    }

    return n;
}

function roundNumber(n) {
    if (n === null || n === undefined) {
        return 0;
    }

    return Math.round(n * 10) / 10;
}

function initials(name) {
    if (!name) {
        return 'ST';
    }

    var parts = String(name).trim().split(/\s+/);
    var result = '';

    if (parts.length > 0) {
        result += parts[0].charAt(0);
    }

    if (parts.length > 1) {
        result += parts[parts.length - 1].charAt(0);
    }

    return result.toUpperCase().substring(0, 2);
}

function statusKey(status) {
    var s = String(status || '').toLowerCase();

    s = s.replace(/[^a-z0-9]+/g, '-');

    if (!s) {
        return 'unknown';
    }

    return s;
}

function scoreWidth(score) {
    if (score === null || score === undefined) {
        return '0%';
    }

    var n = parseFloat(score);

    if (isNaN(n)) {
        return '0%';
    }

    if (n < 0) {
        n = 0;
    }

    if (n > 100) {
        n = 100;
    }

    return n + '%';
}


/* =========================================================
   FIND CURRENT STUDENT
========================================================= */

function findStudent() {

    var requested = $sp.getParameter('student');

    if (!requested) {
        requested = $sp.getParameter('student_id');
    }

    var student = new GlideRecord(STUDENT_TABLE);

    if (requested) {

        student.addQuery('student_id', requested);
        student.setLimit(1);
        student.query();

        if (student.next()) {
            return makeStudent(student);
        }

        student = new GlideRecord(STUDENT_TABLE);

        student.addQuery('sys_id', requested);
        student.setLimit(1);
        student.query();

        if (student.next()) {
            return makeStudent(student);
        }
    }

    var email = '';

    try {
        email = gs.getUser().getEmail();
    } catch (e) {
        email = '';
    }

    if (email) {

        student = new GlideRecord(STUDENT_TABLE);

        student.addQuery('email', email);
        student.setLimit(1);
        student.query();

        if (student.next()) {
            return makeStudent(student);
        }
    }

    student = new GlideRecord(STUDENT_TABLE);

    student.addQuery('student_id', 'STU_TEST_001');
    student.setLimit(1);
    student.query();

    if (student.next()) {
        return makeStudent(student);
    }

    return null;
}


function makeStudent(gr) {

    var studentName = display(
        gr,
        'student_name'
    );

    if (!studentName) {
        studentName = value(
            gr,
            'student_name'
        );
    }

    var studentId = value(
        gr,
        'student_id'
    );

    return {
        sys_id: gr.getUniqueValue(),
        id: studentId,
        name: studentName || studentId,
        initials: initials(studentName || studentId)
    };
}


/* =========================================================
   TRAINER RESOLUTION
========================================================= */

function resolveTrainer(gr, fieldName) {

    var raw = value(gr, fieldName);
    var shown = display(gr, fieldName);

    var trainerId = '';
    var trainerName = '';
    var trainerSysId = '';

    if (isReferenceField(gr, fieldName)) {

        trainerSysId = raw;

        try {

            var ref =
                gr.getElement(fieldName)
                    .getRefRecord();

            if (ref && ref.isValidRecord()) {

                if (ref.isValidField('trainer_id')) {
                    trainerId =
                        value(ref, 'trainer_id');
                }

                if (ref.isValidField('trainer_name')) {

                    trainerName =
                        display(ref, 'trainer_name');

                    if (!trainerName) {
                        trainerName =
                            value(ref, 'trainer_name');
                    }
                }

                if (!trainerName) {
                    trainerName =
                        ref.getDisplayValue();
                }
            }

        } catch (e) {}
    }

    if (!trainerId) {
        trainerId = raw || shown;
    }

    if (!trainerName || !trainerId) {

        var trainer =
            new GlideRecord(TRAINER_TABLE);

        if (trainerId) {

            trainer.addQuery(
                'trainer_id',
                trainerId
            );

            trainer.setLimit(1);
            trainer.query();

            if (trainer.next()) {

                if (!trainerName) {

                    trainerName =
                        display(
                            trainer,
                            'trainer_name'
                        );

                    if (!trainerName) {
                        trainerName =
                            value(
                                trainer,
                                'trainer_name'
                            );
                    }
                }

                if (!trainerId) {
                    trainerId =
                        value(
                            trainer,
                            'trainer_id'
                        );
                }

                trainerSysId =
                    trainer.getUniqueValue();
            }
        }
    }

    if (!trainerName && raw && raw.length == 32) {

        var trainerBySysId =
            new GlideRecord(TRAINER_TABLE);

        if (trainerBySysId.get(raw)) {

            trainerSysId =
                trainerBySysId.getUniqueValue();

            trainerId =
                value(
                    trainerBySysId,
                    'trainer_id'
                );

            trainerName =
                display(
                    trainerBySysId,
                    'trainer_name'
                );

            if (!trainerName) {
                trainerName =
                    value(
                        trainerBySysId,
                        'trainer_name'
                    );
            }
        }
    }

    if (!trainerName) {
        trainerName =
            shown ||
            trainerId ||
            'Trainer';
    }

    if (!trainerId) {
        trainerId =
            raw ||
            shown ||
            '—';
    }

    return {
        key:
            trainerId ||
            trainerSysId ||
            trainerName,

        trainerId:
            trainerId,

        trainerName:
            trainerName,

        initials:
            initials(trainerName)
    };
}


/* =========================================================
   RESOLVE TRAINING PROGRAM
========================================================= */

function resolveTrainingProgram(enrollmentGR) {

    var trainingField =
        'training_program';

    if (!enrollmentGR.isValidField(trainingField)) {
        return null;
    }

    var raw =
        value(
            enrollmentGR,
            trainingField
        );

    if (!raw) {
        return null;
    }

    if (isReferenceField(
        enrollmentGR,
        trainingField
    )) {

        try {

            var ref =
                enrollmentGR
                    .getElement(trainingField)
                    .getRefRecord();

            if (ref && ref.isValidRecord()) {
                return ref;
            }

        } catch (e) {}
    }

    var program =
        new GlideRecord(TRAINING_TABLE);

    program.addQuery(
        'training_id',
        raw
    );

    program.setLimit(1);
    program.query();

    if (program.next()) {
        return program;
    }

    program =
        new GlideRecord(TRAINING_TABLE);

    if (program.get(raw)) {
        return program;
    }

    return null;
}


/* =========================================================
   LOAD STUDENT TRAINING
========================================================= */

function loadTraining(student) {

    var enrollment =
        new GlideRecord(ENROLLMENT_TABLE);

    var studentField =
        'student';

    if (!enrollment.isValidField(studentField)) {
        return;
    }

    if (isReferenceField(
        enrollment,
        studentField
    )) {

        enrollment.addQuery(
            studentField,
            student.sys_id
        );

    } else {

        enrollment.addQuery(
            studentField,
            student.id
        );
    }

    enrollment.orderByDesc(
        'sys_created_on'
    );

    enrollment.query();

    var legacyAssessmentTotal = 0;
    var legacyAssessmentCount = 0;

    while (enrollment.next()) {

        var program =
            resolveTrainingProgram(
                enrollment
            );

        if (!program) {
            continue;
        }

        var trainerInfo =
            resolveTrainer(
                program,
                'trainer'
            );

        var trainingId =
            value(
                program,
                'training_id'
            );

        var trainingName =
            display(
                program,
                'training_name'
            );

        if (!trainingName) {
            trainingName =
                value(
                    program,
                    'training_name'
                );
        }

        var completionStatus =
            display(
                enrollment,
                'completion_status'
            );

        if (!completionStatus) {
            completionStatus =
                value(
                    enrollment,
                    'completion_status'
                );
        }

        if (!completionStatus) {
            completionStatus =
                'Enrolled';
        }

        var attendance =
            numberValue(
                value(
                    enrollment,
                    'attendance'
                )
            );

        var assessmentScore =
            numberValue(
                value(
                    enrollment,
                    'assessment_score'
                )
            );

        if (assessmentScore !== null) {

            legacyAssessmentTotal +=
                assessmentScore;

            legacyAssessmentCount++;
        }

        var progress =
            attendance;

        if (progress === null) {

            if (
                completionStatus
                    .toLowerCase() ==
                'completed'
            ) {

                progress = 100;

            } else {

                progress = 0;
            }
        }

        var completionLabel =
            completionStatus;

        if (
            completionStatus.toLowerCase() ==
            'completed'
        ) {

            completionLabel =
                'Completed';

        } else if (
            completionStatus.toLowerCase() ==
            'in progress'
        ) {

            completionLabel =
                'Not completed';

        } else if (
            completionStatus.toLowerCase() ==
            'enrolled'
        ) {

            completionLabel =
                'Not started';
        }

        var training = {

            enrollmentSysId:
                enrollment.getUniqueValue(),

            trainingSysId:
                program.getUniqueValue(),

            enrollmentId:
                value(
                    enrollment,
                    'enrollment_id'
                ) || '—',

            trainingId:
                trainingId || '—',

            trainingName:
                trainingName ||
                'Training Program',

            skillArea:
                display(
                    program,
                    'skill_area'
                ) ||
                value(
                    program,
                    'skill_area'
                ) ||
                'Skill Development',

            batch:
                display(
                    program,
                    'batch'
                ) ||
                value(
                    program,
                    'batch'
                ) ||
                '—',

            startDate:
                display(
                    program,
                    'start_date'
                ) ||
                value(
                    program,
                    'start_date'
                ) ||
                '—',

            endDate:
                display(
                    program,
                    'end_date'
                ) ||
                value(
                    program,
                    'end_date'
                ) ||
                '—',

            trainerId:
                trainerInfo.trainerId,

            trainerName:
                trainerInfo.trainerName,

            completionStatus:
                completionStatus,

            completionLabel:
                completionLabel,

            statusKey:
                statusKey(
                    completionStatus
                ),

            attendance:
                attendance,

            hasAttendance:
                attendance !== null,

            progressWidth:
                scoreWidth(progress),

            assessmentScore:
                assessmentScore,

            hasAssessment:
                assessmentScore !== null
        };

        data.trainings.push(training);

        var statusLower =
            completionStatus.toLowerCase();

        if (
            statusLower == 'in progress' ||
            statusLower == 'ongoing'
        ) {
            data.summary.inProgress++;
        }

        if (
            statusLower == 'completed'
        ) {
            data.summary.completed++;
        }
    }

    data.summary.trainingCount =
        data.trainings.length;


    /*
     * TRAINER-CREATED ASSIGNMENTS
     */
    loadTrainerAssessments(student);


    /*
     * OLD ENROLLMENT SCORE FALLBACK
     */
    if (
        data.assessments.length === 0 &&
        legacyAssessmentCount > 0
    ) {

        data.summary.hasAssessment =
            true;

        data.summary.avgAssessment =
            roundNumber(
                legacyAssessmentTotal /
                legacyAssessmentCount
            );

        for (
            var i = 0;
            i < data.trainings.length;
            i++
        ) {

            var legacyTraining =
                data.trainings[i];

            if (
                legacyTraining.hasAssessment
            ) {

                data.assessments.push({

                    assessmentKey:
                        'legacy_' +
                        legacyTraining.enrollmentSysId,

                    assignmentSysId:
                        '',

                    enrollmentSysId:
                        legacyTraining.enrollmentSysId,

                    trainingSysId:
                        legacyTraining.trainingSysId,

                    assignmentName:
                        legacyTraining.trainingName +
                        ' Assessment',

                    assignmentType:
                        'Training Assessment',

                    trainingName:
                        legacyTraining.trainingName,

                    trainingId:
                        legacyTraining.trainingId,

                    trainerName:
                        legacyTraining.trainerName,

                    trainerId:
                        legacyTraining.trainerId,

                    score:
                        roundNumber(
                            legacyTraining.assessmentScore
                        ),

                    submissionStatus:
                        'Recorded',

                    dueDate:
                        '',

                    maximumScore:
                        100,

                    description:
                        'Assessment score recorded against your training enrollment.',

                    resourceLink:
                        '',

                    evaluatedDate:
                        '',

                    trainerFeedback:
                        '',

                    attendance:
                        getAttendanceSummary(
                            student,
                            legacyTraining.trainingSysId
                        )
                });
            }
        }

    } else {

        var trainerScoreTotal = 0;
        var trainerScoreCount = 0;

        for (
            var a = 0;
            a < data.assessments.length;
            a++
        ) {

            var trainerAssessment =
                data.assessments[a];

            if (
                trainerAssessment.score !== null
            ) {

                trainerScoreTotal +=
                    trainerAssessment.score;

                trainerScoreCount++;
            }
        }

        data.summary.hasAssessment =
            trainerScoreCount > 0;

        data.summary.avgAssessment =
            trainerScoreCount > 0
                ? roundNumber(
                    trainerScoreTotal /
                    trainerScoreCount
                )
                : 0;
    }
}


/* =========================================================
   LOAD TRAINER CREATED ASSIGNMENTS
========================================================= */

function loadTrainerAssessments(student) {

    data.assessments = [];
    data.assessmentDetails = [];

    for (
        var i = 0;
        i < data.trainings.length;
        i++
    ) {

        var training =
            data.trainings[i];

        loadAssignmentsForTraining(
            student,
            training
        );
    }
}


function loadAssignmentsForTraining(
    student,
    training
) {

    if (
        !training ||
        !training.trainingSysId
    ) {
        return;
    }

    var assignment =
        new GlideRecord(
            ASSIGNMENT_TABLE
        );

    if (
        !assignment.isValidField(
            'training_program'
        )
    ) {
        return;
    }

    assignment.addQuery(
        'training_program',
        training.trainingSysId
    );

    /*
     * Do not show trainer drafts to students.
     */
    if (
        assignment.isValidField('status')
    ) {

        assignment.addQuery(
            'status',
            '!=',
            'Draft'
        );
    }

    assignment.orderByDesc(
        'assigned_date'
    );

    assignment.orderByDesc(
        'sys_created_on'
    );

    assignment.query();

    while (assignment.next()) {

        var assessment =
            buildAssessmentRecord(
                assignment,
                student,
                training
            );

        if (!assessment) {
            continue;
        }

        data.assessments.push(
            assessment
        );

        data.assessmentDetails.push(
            assessment
        );
    }
}


/* =========================================================
   BUILD ASSIGNMENT RECORD
========================================================= */

function buildAssessmentRecord(
    assignment,
    student,
    training
) {

    var assignmentSysId =
        assignment.getUniqueValue();

    var status =
        display(
            assignment,
            'status'
        ) ||
        value(
            assignment,
            'status'
        ) ||
        'Published';

    if (
        String(status).toLowerCase() ==
        'draft'
    ) {
        return null;
    }

    var assignmentName =
        display(
            assignment,
            'assignment_name'
        ) ||
        value(
            assignment,
            'assignment_name'
        ) ||
        'Training Assignment';

    var assignmentType =
        display(
            assignment,
            'assignment_type'
        ) ||
        value(
            assignment,
            'assignment_type'
        ) ||
        'Assignment';

    var maximumScore =
        numberValue(
            value(
                assignment,
                'maximum_score'
            )
        );

    if (maximumScore === null) {
        maximumScore = 100;
    }

    var submission =
        getStudentSubmission(
            assignmentSysId,
            student
        );

    var score =
        submission.score;

    return {

        assessmentKey:
            assignmentSysId +
            '_' +
            student.sys_id,

        assignmentSysId:
            assignmentSysId,

        enrollmentSysId:
            training.enrollmentSysId,

        trainingSysId:
            training.trainingSysId,

        assignmentName:
            assignmentName,

        assignmentType:
            assignmentType,

        assignmentStatus:
            status,

        trainingName:
            training.trainingName,

        trainingId:
            training.trainingId,

        trainerName:
            training.trainerName,

        trainerId:
            training.trainerId,

        score:
            score === null
                ? null
                : roundNumber(score),

        submissionStatus:
            submission.status,

        dueDate:
            display(
                assignment,
                'due_date'
            ) ||
            value(
                assignment,
                'due_date'
            ) ||
            '',

        assignedDate:
            display(
                assignment,
                'assigned_date'
            ) ||
            value(
                assignment,
                'assigned_date'
            ) ||
            '',

        maximumScore:
            maximumScore,

        description:
            value(
                assignment,
                'description'
            ) ||
            display(
                assignment,
                'description'
            ) ||
            '',

        resourceLink:
            value(
                assignment,
                'resource_link'
            ) ||
            '',

        submittedDate:
            submission.submittedDate,

        evaluatedDate:
            submission.evaluatedDate,

        trainerFeedback:
            submission.trainerFeedback,

        submissionLink:
            submission.submissionLink,

        attendance:
            getAttendanceSummary(
                student,
                training.trainingSysId
            )
    };
}


/* =========================================================
   STUDENT ASSIGNMENT SUBMISSION
========================================================= */

function getStudentSubmission(
    assignmentSysId,
    student
) {

    var result = {

        status:
            'Not Submitted',

        score:
            null,

        submittedDate:
            '',

        evaluatedDate:
            '',

        trainerFeedback:
            '',

        submissionLink:
            ''
    };

    var submission =
        new GlideRecord(
            SUBMISSION_TABLE
        );

    if (
        !submission.isValidField(
            'assignment'
        ) ||
        !submission.isValidField(
            'student'
        )
    ) {
        return result;
    }

    submission.addQuery(
        'assignment',
        assignmentSysId
    );

    if (
        isReferenceField(
            submission,
            'student'
        )
    ) {

        submission.addQuery(
            'student',
            student.sys_id
        );

    } else {

        submission.addQuery(
            'student',
            student.id
        );
    }

    submission.orderByDesc(
        'sys_created_on'
    );

    submission.setLimit(1);
    submission.query();

    if (!submission.next()) {
        return result;
    }

    result.status =
        display(
            submission,
            'submission_status'
        ) ||
        value(
            submission,
            'submission_status'
        ) ||
        'Not Submitted';

    result.score =
        numberValue(
            value(
                submission,
                'score'
            )
        );

    result.submittedDate =
        display(
            submission,
            'submitted_date'
        ) ||
        value(
            submission,
            'submitted_date'
        ) ||
        '';

    result.evaluatedDate =
        display(
            submission,
            'evaluated_date'
        ) ||
        value(
            submission,
            'evaluated_date'
        ) ||
        '';

    result.trainerFeedback =
        display(
            submission,
            'trainer_feedback'
        ) ||
        value(
            submission,
            'trainer_feedback'
        ) ||
        '';

    result.submissionLink =
        value(
            submission,
            'submission_link'
        ) ||
        '';

    return result;
}


/* =========================================================
   TRAINING ATTENDANCE
========================================================= */

function getAttendanceSummary(
    student,
    trainingSysId
) {

    var result = {

        totalDays:
            0,

        present:
            0,

        late:
            0,

        absent:
            0,

        percentage:
            0,

        rows:
            []
    };

    if (
        !student ||
        !trainingSysId
    ) {
        return result;
    }

    var attendance =
        new GlideRecord(
            ATTENDANCE_TABLE
        );

    if (
        !attendance.isValidField(
            'student'
        ) ||
        !attendance.isValidField(
            'training_program'
        )
    ) {
        return result;
    }

    if (
        isReferenceField(
            attendance,
            'student'
        )
    ) {

        attendance.addQuery(
            'student',
            student.sys_id
        );

    } else {

        attendance.addQuery(
            'student',
            student.id
        );
    }

    attendance.addQuery(
        'training_program',
        trainingSysId
    );

    attendance.orderBy(
        'attendance_date'
    );

    attendance.query();

    while (attendance.next()) {

        var date =
            display(
                attendance,
                'attendance_date'
            ) ||
            value(
                attendance,
                'attendance_date'
            ) ||
            '—';

        var status =
            display(
                attendance,
                'status'
            ) ||
            value(
                attendance,
                'status'
            ) ||
            'Not Marked';

        var statusLower =
            String(status).toLowerCase();

        if (
            statusLower == 'present'
        ) {

            result.present++;

        } else if (
            statusLower == 'late'
        ) {

            result.late++;

        } else if (
            statusLower == 'absent'
        ) {

            result.absent++;
        }

        result.totalDays++;

        result.rows.push({

            key:
                attendance.getUniqueValue(),

            date:
                date,

            status:
                status,

            statusKey:
                statusKey(status),

            remarks:
                value(
                    attendance,
                    'remarks'
                ) ||
                display(
                    attendance,
                    'remarks'
                ) ||
                ''
        });
    }

    if (
        result.totalDays > 0
    ) {

        result.percentage =
            Math.round(
                (
                    (
                        result.present +
                        result.late
                    ) /
                    result.totalDays
                ) * 100
            );
    }

    return result;
}


/* =========================================================
   LOAD MOCK INTERVIEWS
========================================================= */

function loadInterviews(
    student,
    trainerMap
) {

    var interview =
        new GlideRecord(
            MOCK_INTERVIEW_TABLE
        );

    var studentField =
        'student';

    if (
        !interview.isValidField(
            studentField
        )
    ) {
        return;
    }

    if (
        isReferenceField(
            interview,
            studentField
        )
    ) {

        interview.addQuery(
            studentField,
            student.sys_id
        );

    } else {

        interview.addQuery(
            studentField,
            student.id
        );
    }

    interview.orderByDesc(
        'interview_date'
    );

    interview.orderByDesc(
        'sys_created_on'
    );

    interview.query();

    while (interview.next()) {

        var trainerInfo =
            resolveTrainer(
                interview,
                'trainer'
            );

        var key =
            trainerInfo.key;

        if (!trainerMap[key]) {

            trainerMap[key] = {

                key:
                    key,

                trainerId:
                    trainerInfo.trainerId,

                trainerName:
                    trainerInfo.trainerName,

                initials:
                    trainerInfo.initials,

                interviews:
                    [],

                feedbacks:
                    [],

                interviewCount:
                    0,

                attendedCount:
                    0,

                feedbackCount:
                    0,

                avgOverall:
                    0,

                avgCommunication:
                    0,

                avgTechnical:
                    0,

                avgProblemSolving:
                    0,

                hasOverall:
                    false,

                hasCommunication:
                    false,

                hasTechnical:
                    false,

                hasProblemSolving:
                    false
            };
        }

        var attendanceStatus =
            display(
                interview,
                'attendance_status'
            ) ||
            value(
                interview,
                'attendance_status'
            ) ||
            'Not recorded';

        var attendanceLower =
            attendanceStatus.toLowerCase();

        var attended =
            attendanceLower ==
                'present' ||
            attendanceLower ==
                'attended';

        var interviewId =
            value(
                interview,
                'interview_id'
            ) ||
            display(
                interview,
                'interview_id'
            ) ||
            'Interview';

        var interviewType =
            display(
                interview,
                'interview_type'
            ) ||
            value(
                interview,
                'interview_type'
            ) ||
            'Interview';

        var interviewStatus =
            display(
                interview,
                'interview_status'
            ) ||
            value(
                interview,
                'interview_status'
            ) ||
            '—';

        trainerMap[key]
            .interviews
            .push({

                sys_id:
                    interview.getUniqueValue(),

                interviewId:
                    interviewId,

                interviewType:
                    interviewType,

                interviewDate:
                    display(
                        interview,
                        'interview_date'
                    ),

                startTime:
                    display(
                        interview,
                        'start_time'
                    ),

                endTime:
                    display(
                        interview,
                        'end_time'
                    ),

                attendanceStatus:
                    attendanceStatus,

                interviewStatus:
                    interviewStatus,

                attended:
                    attended,

                initial:
                    interviewId
                        .charAt(0)
                        .toUpperCase()
            });

        trainerMap[key]
            .interviewCount++;

        if (attended) {
            trainerMap[key]
                .attendedCount++;
        }

        data.totalInterviews++;
    }
}


/* =========================================================
   LOAD INTERVIEW FEEDBACK
========================================================= */

function loadFeedback(
    student,
    trainerMap
) {

    var feedback =
        new GlideRecord(
            FEEDBACK_TABLE
        );

    var studentField =
        'student';

    if (
        !feedback.isValidField(
            studentField
        )
    ) {
        return;
    }

    if (
        isReferenceField(
            feedback,
            studentField
        )
    ) {

        feedback.addQuery(
            studentField,
            student.sys_id
        );

    } else {

        feedback.addQuery(
            studentField,
            student.id
        );
    }

    feedback.orderByDesc(
        'feedback_date'
    );

    feedback.orderByDesc(
        'sys_created_on'
    );

    feedback.query();

    while (feedback.next()) {

        var trainerInfo =
            resolveTrainer(
                feedback,
                'trainer'
            );

        var key =
            trainerInfo.key;

        if (!trainerMap[key]) {

            trainerMap[key] = {

                key:
                    key,

                trainerId:
                    trainerInfo.trainerId,

                trainerName:
                    trainerInfo.trainerName,

                initials:
                    trainerInfo.initials,

                interviews:
                    [],

                feedbacks:
                    [],

                interviewCount:
                    0,

                attendedCount:
                    0,

                feedbackCount:
                    0,

                avgOverall:
                    0,

                avgCommunication:
                    0,

                avgTechnical:
                    0,

                avgProblemSolving:
                    0,

                hasOverall:
                    false,

                hasCommunication:
                    false,

                hasTechnical:
                    false,

                hasProblemSolving:
                    false
            };
        }

        var overall =
            numberValue(
                value(
                    feedback,
                    'overall_score'
                )
            );

        var communication =
            numberValue(
                value(
                    feedback,
                    'communication_score'
                )
            );

        var technical =
            numberValue(
                value(
                    feedback,
                    'technical_score'
                )
            );

        var problemSolving =
            numberValue(
                value(
                    feedback,
                    'problem_solving_score'
                )
            );

        var interviewId = '';

        if (
            feedback.isValidField(
                'interview'
            )
        ) {

            if (
                isReferenceField(
                    feedback,
                    'interview'
                )
            ) {

                try {

                    var interviewRef =
                        feedback
                            .getElement(
                                'interview'
                            )
                            .getRefRecord();

                    if (
                        interviewRef &&
                        interviewRef.isValidRecord()
                    ) {

                        interviewId =
                            value(
                                interviewRef,
                                'interview_id'
                            ) ||
                            interviewRef
                                .getDisplayValue();
                    }

                } catch (e) {}

            } else {

                interviewId =
                    display(
                        feedback,
                        'interview'
                    ) ||
                    value(
                        feedback,
                        'interview'
                    );
            }
        }

        var feedbackId =
            value(
                feedback,
                'feedback_id'
            ) ||
            display(
                feedback,
                'feedback_id'
            );

        trainerMap[key]
            .feedbacks
            .push({

                sys_id:
                    feedback.getUniqueValue(),

                feedbackId:
                    feedbackId,

                feedbackDate:
                    display(
                        feedback,
                        'feedback_date'
                    ),

                interviewId:
                    interviewId,

                overallScore:
                    overall === null
                        ? null
                        : roundNumber(
                            overall
                        ),

                communicationScore:
                    communication === null
                        ? null
                        : roundNumber(
                            communication
                        ),

                technicalScore:
                    technical === null
                        ? null
                        : roundNumber(
                            technical
                        ),

                problemSolvingScore:
                    problemSolving === null
                        ? null
                        : roundNumber(
                            problemSolving
                        ),

                hasOverall:
                    overall !== null,

                hasCommunication:
                    communication !== null,

                hasTechnical:
                    technical !== null,

                hasProblemSolving:
                    problemSolving !== null,

                strengths:
                    display(
                        feedback,
                        'strengths'
                    ) ||
                    value(
                        feedback,
                        'strengths'
                    ),

                improvementAreas:
                    display(
                        feedback,
                        'improvement_areas'
                    ) ||
                    value(
                        feedback,
                        'improvement_areas'
                    ),

                recommendation:
                    display(
                        feedback,
                        'recommendation'
                    ) ||
                    value(
                        feedback,
                        'recommendation'
                    )
            });

        trainerMap[key]
            .feedbackCount++;

        data.totalFeedbacks++;
    }
}


/* =========================================================
   TRAINER AVERAGES
========================================================= */

function calculateTrainerAverages(
    trainerMap
) {

    var keys = [];

    for (
        var key in trainerMap
    ) {

        if (
            trainerMap.hasOwnProperty &&
            !trainerMap.hasOwnProperty(key)
        ) {
            continue;
        }

        keys.push(key);
    }

    for (
        var i = 0;
        i < keys.length;
        i++
    ) {

        var trainer =
            trainerMap[keys[i]];

        var overallTotal = 0;
        var overallCount = 0;

        var communicationTotal = 0;
        var communicationCount = 0;

        var technicalTotal = 0;
        var technicalCount = 0;

        var problemTotal = 0;
        var problemCount = 0;

        for (
            var j = 0;
            j < trainer.feedbacks.length;
            j++
        ) {

            var feedback =
                trainer.feedbacks[j];

            if (feedback.hasOverall) {

                overallTotal +=
                    feedback.overallScore;

                overallCount++;
            }

            if (feedback.hasCommunication) {

                communicationTotal +=
                    feedback.communicationScore;

                communicationCount++;
            }

            if (feedback.hasTechnical) {

                technicalTotal +=
                    feedback.technicalScore;

                technicalCount++;
            }

            if (feedback.hasProblemSolving) {

                problemTotal +=
                    feedback.problemSolvingScore;

                problemCount++;
            }
        }

        if (overallCount > 0) {

            trainer.hasOverall = true;

            trainer.avgOverall =
                roundNumber(
                    overallTotal /
                    overallCount
                );
        }

        if (communicationCount > 0) {

            trainer.hasCommunication = true;

            trainer.avgCommunication =
                roundNumber(
                    communicationTotal /
                    communicationCount
                );
        }

        if (technicalCount > 0) {

            trainer.hasTechnical = true;

            trainer.avgTechnical =
                roundNumber(
                    technicalTotal /
                    technicalCount
                );
        }

        if (problemCount > 0) {

            trainer.hasProblemSolving = true;

            trainer.avgProblemSolving =
                roundNumber(
                    problemTotal /
                    problemCount
                );
        }

        trainer.communicationWidth =
            scoreWidth(
                trainer.avgCommunication
            );

        trainer.technicalWidth =
            scoreWidth(
                trainer.avgTechnical
            );

        trainer.problemSolvingWidth =
            scoreWidth(
                trainer.avgProblemSolving
            );

        data.trainers.push(
            trainer
        );
    }
}


/* =========================================================
   MAIN EXECUTION
========================================================= */

var currentStudent =
    findStudent();

if (!currentStudent) {

    data.error =
        'Student record could not be found.';

} else {

    data.student =
        currentStudent;

    loadTraining(
        currentStudent
    );

    var trainerMap = {};

    loadInterviews(
        currentStudent,
        trainerMap
    );

    loadFeedback(
        currentStudent,
        trainerMap
    );

    calculateTrainerAverages(
        trainerMap
    );
}

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
